import{_ as i,l as t,o as e,c as o,v as l,p,x as r,d as s,i as B,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"信息交易概率 PIN","description":"","frontmatter":{"title":"信息交易概率 PIN","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pin.md","filePath":"quant/pin.md","lastUpdated":1789023840000}'),E={name:"quant/pin.md"};function h(m,a,u,P,_,c){const n=t("Mermaid");return e(),o("div",null,[a[1]||(a[1]=l('<h1 id="信息交易概率-pin" tabindex="-1">信息交易概率 PIN <a class="header-anchor" href="#信息交易概率-pin" aria-label="Permalink to &quot;信息交易概率 PIN&quot;">​</a></h1><div class="epigraph"><p>把一天里的买单与卖单计数当成泊松过程的实现，就可以从买卖不平衡里读出「这笔成交有多大概率来自知情交易者」。</p><footer>—— Easley, Kiefer, O&#39;Hara, Paperman, Liquidity, Information, and Infrequently Traded Stocks, Journal of Finance 1996</footer></div><p><a href="/quant/glosten-milgrom">Glosten-Milgrom</a> 与 <a href="/quant/kyle-model">Kyle</a> 把逆向选择写成了理论对象，还没有可估计的数字。本课把序贯交易收到一组泊松到达率上：Easley、Kiefer、O&#39;Hara 与 Paperman 用每日买、卖笔数做极大似然，合成 PIN。它不是高频里的毒性仪表，那是 <a href="/quant/vpin">下一课</a>；PIN 按交易日、用方向计数来估信息不对称。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>做市商无法事先看见谁知情。他只看见一串主动买、主动卖。若某日买单异常多，可能是好消息来了，也可能只是流动性需求碰巧偏向一侧。要把「信息不对称有多严重」从「方向碰巧不平衡」里分开，需要一个生成过程：先抽有没有私有信息，再抽消息好坏，再让两类交易者按不同强度到达。没有这层结构，买卖比只是描述统计，不能叫信息交易概率。</p><p>低频股票尤其尖锐。成交稀疏时，价差里的逆向选择成分很难用高频报价冲击去估；但一整天的买、卖计数仍然可得。EKOP 正是为交易不频繁的股票写的：用日度计数，而不是用逐笔中点收益。问题于是变成：在一个可识别的参数集上，日度 \\((B,S)\\) 的似然能否把「有信息的日子」与「没信息、只有噪声交易」分开。</p><h3 id="序贯交易里的三个未观测层" tabindex="-1">序贯交易里的三个未观测层 <a class="header-anchor" href="#序贯交易里的三个未观测层" aria-label="Permalink to &quot;序贯交易里的三个未观测层&quot;">​</a></h3><p>模型按交易日独立重复。每个交易日开始，以概率 \\(\\alpha\\) 发生一次信息事件；若发生，坏消息的概率是 \\(\\delta\\)，好消息是 \\(1-\\delta\\)。知情交易者只在有事件的日子到达，强度 \\(\\mu\\)：好消息时只买，坏消息时只卖。非知情买家、卖家始终到达，强度各为 \\(\\varepsilon_b\\)、\\(\\varepsilon_s\\)，常取对称 \\(\\varepsilon_b=\\varepsilon_s=\\varepsilon\\)。做市商看到的是泊松计数，看不到 \\(\\alpha\\)、\\(\\delta\\)、\\(\\mu\\)。</p><p><span class="marginnote">PIN 里的「一天」是信息事件的生命周期，不是日历的任意切片。若私有信息在盘中几分钟就释放完，把整日买卖加总会把知情到达稀释进噪声到达。估计窗口与信息衰减必须同一量级，否则 \\(\\alpha\\) 会被估成「几乎天天有事件」的边界解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>观测是每个交易日的买单数 \\(B\\)、卖单数 \\(S\\)（方向通常用 Lee–Ready：成交价相对当时中点，或用报价检验法）。参数 \\(\\theta=(\\alpha,\\delta,\\mu,\\varepsilon_b,\\varepsilon_s)\\)。无事件日，\\((B,S)\\) 是两路独立泊松；好消息日，买的强度变成 \\(\\varepsilon_b+\\mu\\)；坏消息日，卖的强度变成 \\(\\varepsilon_s+\\mu\\)。日似然是三种体制的混合：</p> \\[\\begin{aligned} L(\\theta\\mid B,S) &amp;= (1-\\alpha) e^{-\\varepsilon_b-\\varepsilon_s}\\frac{\\varepsilon_b^{B}\\varepsilon_s^{S}}{B!S!} + \\alpha(1-\\delta) e^{-(\\mu+\\varepsilon_b+\\varepsilon_s)}\\frac{(\\mu+\\varepsilon_b)^{B}\\varepsilon_s^{S}}{B!S!} \\\\ &amp;\\quad + \\alpha\\delta\\, e^{-(\\mu+\\varepsilon_b+\\varepsilon_s)}\\frac{\\varepsilon_b^{B}(\\mu+\\varepsilon_s)^{S}}{B!S!}. \\end{aligned} \\]<p>\\(T\\) 个交易日独立，总似然是日似然的乘积。极大似然给出 \\(\\hat\\theta\\)，再定义</p> \\[\\mathrm{PIN}=\\frac{\\alpha\\mu}{\\alpha\\mu+2\\varepsilon}, \\]<p>分母是总到达率（对称非知情时），分子是知情到达的期望。直觉：随机抽到的一笔成交，来自知情者的概率。Easley、Hvidkjaer、O&#39;Hara（2002）用滚动窗口的 PIN 作为个股信息风险，放进横截面收益回归，问它能否解释收益率——这是 PIN 从微观结构度量走进资产定价的那一步。</p><h3 id="方向分类先于似然" tabindex="-1">方向分类先于似然 <a class="header-anchor" href="#方向分类先于似然" aria-label="Permalink to &quot;方向分类先于似然&quot;">​</a></h3><p>似然吃的是 \\((B,S)\\)，不是原始成交价。Lee–Ready 把成交价高于中点标成买、低于中点标成卖，等于中点时用tick 检验。分类错误会把知情造成的真实不平衡抹平，使 PIN 偏低；在买卖价差只有一两个最小报价单位、中点频繁被跨越的股票上，这个偏差不是小修正。工程上应固定一套分类规则、一套开盘集合竞价是否计入的口径，再谈 PIN 的时间序列。不要把不同数据商的「主动买」字段当成已经校准过的 \\(B\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>识别来自混合分布的形状，而不是来自某一日的买卖比。无事件日，\\(B\\) 与 \\(S\\) 都集中在 \\(\\varepsilon\\) 附近；有事件日，一侧会被 \\(\\mu\\) 拉到远处。样本里若既有「买卖都中等」的日子，又有「一侧极端」的日子，似然就能把 \\(\\alpha\\) 从 \\(\\mu\\) 里分开：极端日的频率帮着认 \\(\\alpha\\)，极端的幅度帮着认 \\(\\mu\\)。若所有日子都轻度不平衡，\\(\\alpha\\) 与 \\(\\mu\\) 会沿着 \\(\\alpha\\mu\\) 近似不可分，PIN 仍可能稳住，分项不稳。</p><p>做市商的报价在模型里由贝叶斯更新给出：看到一笔买，后验里好消息的权重上升，卖价上调。PIN 高意味着逆向选择严重，价差应更宽——这是 EKOP 用来对照低频股流动性的通道。它不描述盘中的瞬时毒性，也不对成交量时钟负责。</p><p><span class="marginnote">\\(\\mathrm{PIN}=\\alpha\\mu/(\\alpha\\mu+2\\varepsilon)\\) 对 \\(\\varepsilon\\) 的水平很敏感。成交量长期上涨时，若知情强度跟不上噪声交易的膨胀，\\(\\varepsilon\\) 变大，PIN 机械下降。这不是信息不对称消失了，是分母被流动性交易撑大了。跨年代比较 PIN 水平，必须先处理交易频率的非平稳。</span></p><h3 id="边界解与数值似然" tabindex="-1">边界解与数值似然 <a class="header-anchor" href="#边界解与数值似然" aria-label="Permalink to &quot;边界解与数值似然&quot;">​</a></h3><p>\\(\\alpha\\) 或 \\(\\delta\\) 经常撞到 0 或 1。对数似然里有阶乘与很大的泊松均值，直接算 \\(e^{-\\lambda}\\lambda^{B}/B!\\) 会溢出；应在对数空间用 Stirling 或库函数的泊松概率。多起点优化是常规，因为混合模型的似然非凹。报告 PIN 时应同时报告撞边界的窗口比例：若一半窗口 \\(\\hat\\alpha=1\\)，那条 PIN 时间序列不能当连续的信息风险因子用。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>PIN 假定信息事件按日开关、日内强度为常数、买卖方向可观测、日与日独立。连续竞价、隐藏单、中午休市、开收盘集合竞价，都会破坏「一天一个泊松实验」的口径。高频下逐笔到达远不是泊松，日度加总只是让中心极限把计数推回可处理的形状，并不证明数据生成过程正确。</p><p>不要把 PIN 当成实时风控指标：一天结束才能更新一次完整似然（或至少要攒够一个估计窗）。不要与 <a href="/quant/vpin">VPIN</a> 互换：后者用成交量桶和批量分类，连似然都可以不做。不要在最小报价单位变动、拆股、停牌复牌的日子上硬跑同一套 \\((B,S)\\)。资产定价用途上，PIN 与流动性、换手高度相关，横截面里要说清它是信息风险还是流动性的代理；Easley–Hvidkjaer–O&#39;Hara 的结论依赖样本期与控制变量，后续文献并不一致。</p><p><span class="marginnote">中国 A 股的集合竞价、涨跌停与 T+1 会改变「知情者一天内能下多少单」。把 EKOP 的美股日历直接套到沪深，先要定义：集合竞价的成交算不算进 \\(B,S\\)，涨停只剩买时 \\(\\mu\\) 是否还可识别。PIN 公式没变，实验设计已经变了。</span></p>',27)),(e(),p(d,null,{default:r(()=>[B(n,{id:"mermaid-75",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BB%A5%E6%A6%82%E7%8E%87%20%CE%B1%20%E6%8A%BD%E4%BF%A1%E6%81%AF%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20G%5B%22%E5%A5%BD%E6%B6%88%E6%81%AF%201-%CE%B4%22%5D%0A%20%20A%20--%3E%20N%5B%22%E6%97%A0%E4%BA%8B%E4%BB%B6%201-%CE%B1%22%5D%0A%20%20A%20--%3E%20B%5B%22%E5%9D%8F%E6%B6%88%E6%81%AF%20%CE%B4%22%5D%0A%20%20G%20--%3E%20PB%5B%22%E4%B9%B0%E5%BC%BA%E5%BA%A6%20%CE%B5%2B%CE%BC%20%2F%20%E5%8D%96%E5%BC%BA%E5%BA%A6%20%CE%B5%22%5D%0A%20%20N%20--%3E%20PN%5B%22%E4%B9%B0%20%CE%B5%20%2F%20%E5%8D%96%20%CE%B5%22%5D%0A%20%20B%20--%3E%20PS%5B%22%E4%B9%B0%20%CE%B5%20%2F%20%E5%8D%96%20%CE%B5%2B%CE%BC%22%5D%0A%20%20PB%20--%3E%20BS%5B%22%E6%97%A5%E8%AE%A1%E6%95%B0%20B%2C%20S%22%5D%0A%20%20PN%20--%3E%20BS%0A%20%20PS%20--%3E%20BS%0A%20%20BS%20--%3E%20MLE%5B%22%E6%9E%81%E5%A4%A7%E4%BC%BC%E7%84%B6%20%CE%B8%22%5D%0A%20%20MLE%20--%3E%20PIN%5B%22PIN%20%3D%20%CE%B1%CE%BC%20%2F%20(%CE%B1%CE%BC%2B2%CE%B5)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PIN 来自 EKOP 序贯交易模型：信息事件概率 \\(\\alpha\\)、知情到达 \\(\\mu\\)、非知情到达 \\(\\varepsilon\\)，用日度买卖计数做混合泊松极大似然。</li><li>\\(\\mathrm{PIN}=\\alpha\\mu/(\\alpha\\mu+2\\varepsilon)\\) 是随机一笔成交来自知情者的概率，不是盘中实时毒性。</li><li>方向分类误差、成交量非平稳、边界解，都会让水平不可比；应固定口径并报告撞边界比例。</li><li>它解释价差里的逆向选择，也被拿到横截面收益里当信息风险，但与流动性代理高度纠缠。</li><li>不要与 VPIN 混用：一个是日度似然，一个是成交量时钟上的不平衡。</li><li>出处：Easley, Kiefer, O&#39;Hara, Paperman, <em>Liquidity, Information, and Infrequently Traded Stocks</em>, Journal of Finance 1996；定价应用见 Easley, Hvidkjaer, O&#39;Hara, <em>Is Information Risk a Determinant of Asset Returns?</em>, Journal of Finance 2002。</li></ul>',2))])}const v=i(E,[["render",h]]);export{f as __pageData,v as default};
